27	// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
28	// When a generation reaches this many checkpoints, it is archived
29	// and a fresh /full/current is created.
30	const DefaultMaxCheckpointsPerGeneration = 100
31	
32	// GenerationMetadata tracks the state of a /full/* generation.
33	// Written to the tree root as generation.json at archive time only — not during
34	// normal writes to /full/current. This keeps /full/current free of root-level
35	// files, ensuring conflict-free tree merges during push recovery.
36	//
37	// The generation's sequence number is derived from the ref name, not stored here.
38	// Checkpoint membership is determined by walking the tree (shard directories).
39	type GenerationMetadata struct {
40		// OldestCheckpointAt is the creation time of the earliest checkpoint.
41		OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`
42	
43		// NewestCheckpointAt is the creation time of the most recent checkpoint.
44		NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
45	}
46	
47	// ReadGeneration reads generation.json from the given tree hash.
48	// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
49	func (s *V2GitStore) ReadGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
50		if treeHash == plumbing.ZeroHash {
51			return GenerationMetadata{}, nil
52		}
53	
54		tree, err := s.repo.TreeObject(treeHash)
55		if err != nil {
56			return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
57		}
58	
59		file, err := tree.File(paths.GenerationFileName)
60		if err != nil {
61			if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
62				return GenerationMetadata{}, nil
63			}
64			return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
65		}
66	
67		content, err := file.Contents()
68		if err != nil {
69			return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
70		}
71	
72		var gen GenerationMetadata
73		if err := json.Unmarshal([]byte(content), &gen); err != nil {
74			return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
75		}
76	
77		return gen, nil
78	}
79	
80	// ReadGenerationFromRef reads generation.json from the tree pointed to by the given ref.
81	func (s *V2GitStore) ReadGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
82		_, treeHash, err := s.GetRefState(refName)
83		if err != nil {
84			return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
85		}
86		return s.ReadGeneration(treeHash)
87	}
88	
89	// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
90	// Returns a TreeEntry ready to be placed in a tree.
91	func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
92		data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
93		if err != nil {
94			return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
95		}
96	
97		blobHash, err := CreateBlobFromContent(s.repo, data)
98		if err != nil {
99			return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
100		}
101	
102		return object.TreeEntry{
103			Name: paths.GenerationFileName,
104			Mode: filemode.Regular,
105			Hash: blobHash,
106		}, nil
107	}
108	
109	// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
110	func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
111		entry, err := s.marshalGenerationBlob(gen)
112		if err != nil {
113			return err
114		}
115		entries[paths.GenerationFileName] = entry
116		return nil
117	}
118	
119	// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
120	// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
121	// across all shard prefixes. Returns 0 for an empty tree.
122	func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
123		if treeHash == plumbing.ZeroHash {
124			return 0, nil
125		}
126	
127		tree, err := s.repo.TreeObject(treeHash)
128		if err != nil {
129			return 0, fmt.Errorf("failed to read tree: %w", err)
130		}
131	
132		count := 0
133		if err := WalkCheckpointShards(s.repo, tree, func(_ id.CheckpointID, _ plumbing.Hash) error {
134			count++
135			return nil
136		}); err != nil {
137			return 0, err
138		}
139	
140		return count, nil
141	}
142	
143	// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
144	// a new root tree hash. Preserves all existing entries (shard directories, etc.).
145	func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
146		entry, err := s.marshalGenerationBlob(gen)
147		if err != nil {
148			return plumbing.ZeroHash, err
149		}
150	
151		return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
152			UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
153	}
