155	// ComputeGenerationCheckpointTimestamps derives timestamps from the checkpoints
156	// present in a /full/* tree. It prefers created_at from v2 /main metadata and
157	// falls back to top-level transcript event timestamps for older or partial v2 data.
158	func (s *V2GitStore) ComputeGenerationCheckpointTimestamps(rootTreeHash plumbing.Hash) (GenerationMetadata, bool, error) {
159		if rootTreeHash == plumbing.ZeroHash {
160			return GenerationMetadata{}, false, nil
161		}
162	
163		rootTree, err := s.repo.TreeObject(rootTreeHash)
164		if err != nil {
165			return GenerationMetadata{}, false, fmt.Errorf("failed to read generation tree: %w", err)
166		}
167	
168		mainTree, mainTreeErr := s.v2MainTree()
169		if mainTreeErr != nil {
170			mainTree = nil
171		}
172	
173		var gen GenerationMetadata
174		found := false
175		missingCheckpointTimestamp := false
176		err = WalkCheckpointShards(s.repo, rootTree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
177			if mainTree != nil {
178				if cpGen, ok := s.checkpointTimestampRangeFromMain(mainTree, cpID); ok {
179					mergeGenerationRange(&gen, &found, cpGen)
180					return nil
181				}
182			}
183	
184			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
185			if treeErr != nil {
186				missingCheckpointTimestamp = true
187				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
188			}
189			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
190				mergeGenerationRange(&gen, &found, cpGen)
191				return nil
192			}
193			missingCheckpointTimestamp = true
194			return nil
195		})
196		if err != nil {
197			return GenerationMetadata{}, false, err
198		}
199		if missingCheckpointTimestamp {
200			return GenerationMetadata{}, false, nil
201		}
202	
203		return gen, found, nil
204	}
