216		}
217	
218		var gen GenerationMetadata
219		found := false
220		missingCheckpointTimestamp := false
221		err = WalkCheckpointShards(s.repo, rootTree, func(_ id.CheckpointID, cpTreeHash plumbing.Hash) error {
222			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
223			if treeErr != nil {
224				missingCheckpointTimestamp = true
225				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
226			}
227			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
228				mergeGenerationRange(&gen, &found, cpGen)
