244	// computeGenerationTimestamps derives timestamps for a generation being archived.
245	// It uses checkpoint metadata/transcript timestamps rather than git commit times
246	// so migration and ref-repair commits don't reset retention age.
247	func (s *V2GitStore) computeGenerationTimestamps(rootTreeHash plumbing.Hash) GenerationMetadata {
248		if gen, ok, err := s.ComputeGenerationCheckpointTimestamps(rootTreeHash); err == nil && ok {
249			return gen
250		}
251		return s.computeGenerationTimestampsFromCommitHistory()
252	}
