254	func (s *V2GitStore) computeGenerationTimestampsFromCommitHistory() GenerationMetadata {
255		now := time.Now().UTC()
256		fallback := GenerationMetadata{OldestCheckpointAt: now, NewestCheckpointAt: now}
257	
258		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
259		ref, err := s.repo.Reference(refName, true)
260		if err != nil {
261			return fallback
262		}
263	
264		commit, err := s.repo.CommitObject(ref.Hash())
265		if err != nil {
266			return fallback
267		}
268	
269		newest := commit.Committer.When.UTC()
270	
271		// Walk parents to find the oldest commit in this generation
272		iter := commit
273		for len(iter.ParentHashes) > 0 {
274			parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
275			if parentErr != nil {
276				break
277			}
278			iter = parent
279		}
280		oldest := iter.Committer.When.UTC()
281	
282		return GenerationMetadata{
283			OldestCheckpointAt: oldest,
284			NewestCheckpointAt: newest,
285		}
286	}
