304	func (s *V2GitStore) checkpointTimestampRangeFromMain(mainTree *object.Tree, cpID id.CheckpointID) (GenerationMetadata, bool) {
305		cpTree, err := mainTree.Tree(cpID.Path())
306		if err != nil {
307			return GenerationMetadata{}, false
308		}
309	
310		var gen GenerationMetadata
311		found := false
312		for _, entry := range cpTree.Entries {
313			if entry.Mode != filemode.Dir {
314				continue
315			}
316			if _, err := strconv.Atoi(entry.Name); err != nil {
317				continue
318			}
319			sessionTree, err := s.repo.TreeObject(entry.Hash)
320			if err != nil {
321				continue
322			}
323			metadataFile, err := sessionTree.File(paths.MetadataFileName)
324			if err != nil {
325				continue
326			}
327			metadataContent, err := metadataFile.Contents()
328			if err != nil {
329				continue
330			}
331			var metadata CommittedMetadata
332			if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil || metadata.CreatedAt.IsZero() {
333				continue
334			}
335			mergeGenerationTime(&gen, &found, metadata.CreatedAt.UTC())
336		}
337		return gen, found
338	}
