340	func checkpointTimestampRangeFromFullTree(cpTree *object.Tree) (GenerationMetadata, bool) {
341		var gen GenerationMetadata
342		found := false
343		for _, entry := range cpTree.Entries {
344			if entry.Mode != filemode.Dir {
345				continue
346			}
347			if _, err := strconv.Atoi(entry.Name); err != nil {
348				continue
349			}
350			sessionTree, err := cpTree.Tree(entry.Name)
351			if err != nil {
352				continue
353			}
354			transcript, err := readTranscriptFromObjectTree(sessionTree, "")
355			if err != nil || len(transcript) == 0 {
356				continue
357			}
358			if transcriptGen, ok := timestampRangeFromTranscript(transcript); ok {
359				mergeGenerationRange(&gen, &found, transcriptGen)
360			}
361		}
362		return gen, found
363	}
364	
365	func timestampRangeFromTranscript(transcript []byte) (GenerationMetadata, bool) {
366		reader := bufio.NewReader(bytes.NewReader(transcript))
367		var gen GenerationMetadata
368		found := false
369	
370		for {
371			line, err := reader.ReadBytes('\n')
372			if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
373				var event struct {
374					Timestamp string `json:"timestamp"`
375				}
376				if jsonErr := json.Unmarshal(trimmed, &event); jsonErr == nil && event.Timestamp != "" {
377					if ts, parseErr := time.Parse(time.RFC3339Nano, event.Timestamp); parseErr == nil {
378						mergeGenerationTime(&gen, &found, ts.UTC())
379					}
380				}
381			}
382			if errors.Is(err, io.EOF) {
383				break
384			}
385			if err != nil {
386				break
387			}
388		}
389	
390		return gen, found
391	}
