393	func mergeGenerationRange(dst *GenerationMetadata, found *bool, src GenerationMetadata) {
394		mergeGenerationTime(dst, found, src.OldestCheckpointAt)
395		mergeGenerationTime(dst, found, src.NewestCheckpointAt)
396	}
