398	func mergeGenerationTime(gen *GenerationMetadata, found *bool, ts time.Time) {
399		if ts.IsZero() {
400			return
401		}
402		ts = ts.UTC()
403		if !*found {
404			gen.OldestCheckpointAt = ts
405			gen.NewestCheckpointAt = ts
406			*found = true
407			return
408		}
409		if ts.Before(gen.OldestCheckpointAt) {
410			gen.OldestCheckpointAt = ts
411		}
412		if ts.After(gen.NewestCheckpointAt) {
413			gen.NewestCheckpointAt = ts
414		}
415	}
