424	// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
425	func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
426		refs, err := s.repo.References()
427		if err != nil {
428			return nil, fmt.Errorf("failed to list references: %w", err)
429		}
430	
431		var archived []string
432		err = refs.ForEach(func(ref *plumbing.Reference) error {
433			name := ref.Name().String()
434			if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
435				return nil
