437			suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
438			if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
439				return nil
440			}
441			archived = append(archived, suffix)
442			return nil
443		})
444		if err != nil {
445			return nil, fmt.Errorf("failed to iterate references: %w", err)
446		}
447	
448		sort.Strings(archived)
