452	// nextGenerationNumber returns the next sequential generation number for archiving.
453	// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
454	func (s *V2GitStore) nextGenerationNumber() (int, error) {
455		archived, err := s.ListArchivedGenerations()
456		if err != nil {
457			return 0, err
458		}
459	
460		var maxNum int64
461		for _, name := range archived {
462			n, parseErr := strconv.ParseInt(name, 10, 64)
463			if parseErr != nil {
464				continue // skip unparseable entries
465			}
466			if n > maxNum {
467				maxNum = n
468			}
469		}
470		return int(maxNum) + 1, nil
471	}
