473	// rotateGeneration archives the current /full/current generation and creates
474	// a fresh orphan. This is a 2-phase operation:
475	//
476	//  1. Archive: determine the next generation number, create a new ref pointing
477	//     to the current /full/current commit.
478	//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
479	//     point /full/current at it.
480	func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
481		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
482	
483		// Guard against concurrent rotation: re-read /full/current and check if
484		// it's still above the threshold. If not, another instance already rotated.
485		_, currentTreeHash, err := s.GetRefState(refName)
486		if err != nil {
487			return fmt.Errorf("rotation: failed to read /full/current: %w", err)
488		}
489		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
490		if err != nil {
491			return fmt.Errorf("rotation: failed to count checkpoints: %w", err)
492		}
493		if checkpointCount < s.maxCheckpoints() {
494			return nil
495		}
496	
497		currentRef, err := s.repo.Reference(refName, true)
498		if err != nil {
499			return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
500		}
501	
502		archiveNumber, err := s.nextGenerationNumber()
503		if err != nil {
504			return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
505		}
506	
507		// Phase 1: Archive — create ref pointing to the current commit.
508		// If the archive ref already exists, another instance already rotated — skip.
509		archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
510		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
511			logging.Info(ctx, "rotation: archive ref already exists, skipping",
512				slog.String("archive_ref", string(archiveRefName)),
513			)
514			return nil
515		}
516		archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
517		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
518			return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
519		}
520	
521		// Verify /full/current hasn't been advanced by another writer since we read it.
522		// If it changed, abort — the archive ref is harmless (points to a valid commit)
523		// and the next writer will trigger rotation again.
524		postArchiveRef, err := s.repo.Reference(refName, true)
525		if err != nil {
526			return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
527		}
528		if postArchiveRef.Hash() != currentRef.Hash() {
529			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
530			return nil
531		}
532	
533		// Write generation.json to the current tree before archiving.
534		gen := s.computeGenerationTimestamps(currentTreeHash)
535		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
536		if err != nil {
537			return fmt.Errorf("rotation: failed to add generation.json: %w", err)
538		}
539	
540		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
541		archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
542		if err != nil {
543			return fmt.Errorf("rotation: failed to create archive commit: %w", err)
544		}
545	
546		// Update the archive ref to point to the commit with generation.json
547		archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
548		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
549			return fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
550		}
551	
552		// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
553		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
554		if err != nil {
555			return fmt.Errorf("rotation: failed to build empty tree: %w", err)
556		}
557	
558		orphanCommitHash, err := CreateCommit(ctx, s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
559		if err != nil {
560			return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
561		}
562	
563		orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
564		if err := s.repo.Storer.SetReference(orphanRef); err != nil {
565			return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
566		}
567	
568		logging.Info(ctx, "generation rotation complete",
569			slog.Int("archived_generation", archiveNumber),
570			slog.String("archive_ref", string(archiveRefName)),
571		)
572	
573		return nil
574	}
