405			if refOID == "" {
406				refOID = commitHash.String()
407			}
408			cleanupItems = append(cleanupItems, CleanupItem{
409				Type:   CleanupTypeV2Generation,
410				ID:     candidate.Name,
411				RefOID: refOID,
412				Reason: "expired archived full transcript generation",
413			})
414		}
415	
416		return cleanupItems, warnings, nil
417	}
