426	func listArchivedV2GenerationCandidates(
427		ctx context.Context,
428		repo *git.Repository,
429		store *checkpoint.V2GitStore,
430	) ([]archivedV2GenerationCandidate, []plumbing.ReferenceName, []string, error) {
431		localNames, err := store.ListArchivedGenerations()
432		if err != nil {
433			return nil, nil, nil, fmt.Errorf("list local archived generations: %w", err)
434		}
435	
436		candidatesByName := make(map[string]archivedV2GenerationCandidate, len(localNames))
437		for _, name := range localNames {
438			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + name)
439			ref, refErr := repo.Reference(refName, true)
440			if refErr != nil {
441				continue
442			}
443			candidatesByName[name] = archivedV2GenerationCandidate{
444				Name:    name,
445				RefName: refName,
446				RefOID:  ref.Hash().String(),
447			}
448		}
449	
450		var warnings []string
451		var tempRefs []plumbing.ReferenceName
452		target, targetErr := remote.FetchURL(ctx)
453		if targetErr == nil && target != "" {
454			remoteRefs, remoteErr := listRemoteArchivedV2GenerationRefs(ctx, target)
455			if remoteErr != nil {
456				warnings = append(warnings, fmt.Sprintf("failed to list remote v2 generations: %v", remoteErr))
457			} else {
458				fetchTarget, fetchTargetErr := remote.ResolveFetchTarget(ctx, target)
459				if fetchTargetErr != nil {
460					warnings = append(warnings, fmt.Sprintf("failed to resolve remote for v2 generation fetch: %v", fetchTargetErr))
461				} else {
462					for name, remoteOID := range remoteRefs {
463						if candidate, ok := candidatesByName[name]; ok && candidate.RefOID == remoteOID {
464							candidate.RemoteOID = remoteOID
465							candidatesByName[name] = candidate
466							continue
467						}
468						tempRef, fetchErr := fetchArchivedV2Generation(ctx, fetchTarget, name)
469						if fetchErr != nil {
470							warnings = append(warnings, fmt.Sprintf("generation %s: failed to fetch remote ref: %v", name, fetchErr))
471							continue
472						}
473						tempRefs = append(tempRefs, tempRef)
474						candidatesByName[name] = archivedV2GenerationCandidate{
475							Name:      name,
476							RefName:   tempRef,
477							RefOID:    remoteOID,
478							RemoteOID: remoteOID,
479						}
480					}
481				}
482			}
483		}
484	
485		names := make([]string, 0, len(candidatesByName))
486		for name := range candidatesByName {
487			names = append(names, name)
488		}
489		sort.Strings(names)
490	
491		candidates := make([]archivedV2GenerationCandidate, 0, len(names))
492		for _, name := range names {
493			candidates = append(candidates, candidatesByName[name])
494		}
495		return candidates, tempRefs, warnings, nil
496	}
