498	func listRemoteArchivedV2GenerationRefs(ctx context.Context, target string) (map[string]string, error) {
499		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
500		if err != nil {
501			return nil, fmt.Errorf("ls remote v2 generations: %w", err)
502		}
503	
504		refs := make(map[string]string)
505		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
506			if line == "" {
507				continue
508			}
509			parts := strings.Fields(line)
510			if len(parts) < 2 {
511				continue
512			}
513			refName := parts[1]
514			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
515			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
516				continue
517			}
518			refs[suffix] = parts[0]
519		}
520		return refs, nil
521	}
