523	func fetchArchivedV2Generation(ctx context.Context, fetchTarget, name string) (plumbing.ReferenceName, error) {
524		refName := paths.V2FullRefPrefix + name
525		tempRef := plumbing.ReferenceName("refs/entire-clean-tmp/v2/full/" + name)
526		refSpec := fmt.Sprintf("+%s:%s", refName, tempRef)
527		if output, err := remote.Fetch(ctx, remote.FetchOptions{
528			Remote:   fetchTarget,
529			RefSpecs: []string{refSpec},
530			NoTags:   true,
531			NoFilter: true,
532		}); err != nil {
533			return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
534		}
535		return tempRef, nil
536	}
