20		Skipped  []string
21		Failed   []string
22		Warnings []string
23	}
24	
25	// RepairV2GenerationMetadata rewrites generation.json for archived v2 /full/*
26	// generation refs using the timestamp envelope from raw transcripts. Remote
27	// archived refs are repaired with force-with-lease when they exist on the
28	// checkpoint remote.
29	func RepairV2GenerationMetadata(ctx context.Context) (*RepairV2GenerationMetadataResult, error) {
30		repo, err := OpenRepository(ctx)
31		if err != nil {
32			return nil, fmt.Errorf("failed to open git repository: %w", err)
33		}
34	
35		store := checkpoint.NewV2GitStore(repo, "origin")
36		return repairV2GenerationMetadata(ctx, repo, store)
37	}
38	
39	func repairV2GenerationMetadata(ctx context.Context, repo *git.Repository, store *checkpoint.V2GitStore) (*RepairV2GenerationMetadataResult, error) {
40		candidates, tempRefs, warnings, err := listArchivedV2GenerationCandidates(ctx, repo, store)
41		if err != nil {
42			return nil, fmt.Errorf("failed to list archived generations: %w", err)
43		}
44		defer removeTempRefs(repo, tempRefs)
45	
46		result := &RepairV2GenerationMetadataResult{
47			Warnings: warnings,
48		}
49	
50		pushTarget, pushTargetErr := repairPushTarget(ctx, candidates)
51		if pushTargetErr != nil {
52			result.Warnings = append(result.Warnings, pushTargetErr.Error())
53		}
54	
55		for _, candidate := range candidates {
56			repaired, repairErr := repairOneV2GenerationMetadata(ctx, repo, store, candidate, pushTarget, pushTargetErr)
57			if repairErr != nil {
58				result.Failed = append(result.Failed, candidate.Name)
59				result.Warnings = append(result.Warnings, fmt.Sprintf("generation %s: %v", candidate.Name, repairErr))
60				continue
61			}
62			if repaired {
63				result.Repaired = append(result.Repaired, candidate.Name)
64			} else {
65				result.Skipped = append(result.Skipped, candidate.Name)
66			}
67		}
68	
69		return result, nil
70	}
71	
72	func repairOneV2GenerationMetadata(
73		ctx context.Context,
74		repo *git.Repository,
75		store *checkpoint.V2GitStore,
76		candidate archivedV2GenerationCandidate,
77		pushTarget string,
78		pushTargetErr error,
79	) (bool, error) {
80		oldCommitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
81		if refErr != nil {
82			return false, fmt.Errorf("cannot read ref: %w", refErr)
83		}
84	
85		gen, found, timestampErr := store.ComputeGenerationRawTranscriptTimestamps(treeHash)
86		if timestampErr != nil {
87			return false, fmt.Errorf("failed to compute raw transcript timestamps: %w", timestampErr)
88		}
89		if !found {
90			return false, nil
91		}
92	
93		current, genErr := store.ReadGeneration(treeHash)
94		if genErr != nil {
95			return false, fmt.Errorf("failed to read generation.json: %w", genErr)
96		}
97		if generationMetadataEqual(current, gen) {
98			return false, nil
99		}
100	
101		newTreeHash, addErr := store.AddGenerationJSONToTree(treeHash, gen)
102		if addErr != nil {
103			return false, fmt.Errorf("failed to rewrite generation.json: %w", addErr)
104		}
105		if newTreeHash == treeHash {
106			return false, nil
107		}
108	
109		newCommitHash, commitErr := checkpoint.CreateCommit(ctx, repo, newTreeHash, oldCommitHash,
110			fmt.Sprintf("Repair generation metadata: %s\n", candidate.Name),
111			"Entire Migration", "migration@entire.dev")
112		if commitErr != nil {
113			return false, fmt.Errorf("failed to create repair commit: %w", commitErr)
114		}
115	
116		if err := repo.Storer.SetReference(plumbing.NewHashReference(candidate.RefName, newCommitHash)); err != nil {
117			return false, fmt.Errorf("failed to update ref %s: %w", candidate.RefName, err)
118		}
119	
120		if candidate.RemoteOID == "" {
121			return true, nil
122		}
123		if pushTargetErr != nil {
124			return false, fmt.Errorf("failed to resolve remote for generation metadata repair push: %w", pushTargetErr)
125		}
126		if pushTarget == "" {
127			return false, errors.New("no push target available for remote generation metadata repair")
128		}
129	
130		remoteRefName := paths.V2FullRefPrefix + candidate.Name
131		if err := pushRepairedV2Generation(ctx, pushTarget, candidate.RefName.String(), remoteRefName, candidate.RemoteOID); err != nil {
132			return false, err
133		}
134		return true, nil
135	}
136	
137	func repairPushTarget(ctx context.Context, candidates []archivedV2GenerationCandidate) (string, error) {
138		for _, candidate := range candidates {
139			if candidate.RemoteOID != "" {
140				target, _, err := remote.PushURL(ctx, "origin")
141				if err != nil {
142					return "", fmt.Errorf("push URL: %w", err)
143				}
144				return target, nil
145			}
146		}
147		return "", nil
148	}
149	
150	func pushRepairedV2Generation(ctx context.Context, target, sourceRef, remoteRef, expectedOID string) error {
151		extraArgs := []string{}
152		if expectedOID != "" {
153			extraArgs = append(extraArgs, fmt.Sprintf("--force-with-lease=%s:%s", remoteRef, expectedOID))
154		}
155		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
156			Remote:    target,
157			RefSpecs:  []string{sourceRef + ":" + remoteRef},
158			ExtraArgs: extraArgs,
159		})
160		if err != nil {
161			output := strings.TrimSpace(result.Output)
162			if output != "" {
163				return fmt.Errorf("%s: %w", output, err)
164			}
165			return fmt.Errorf("push repaired generation ref %s: %w", remoteRef, err)
166		}
167		return nil
168	}
169	
170	func generationMetadataEqual(left, right checkpoint.GenerationMetadata) bool {
171		return left.OldestCheckpointAt.Equal(right.OldestCheckpointAt) &&
172			left.NewestCheckpointAt.Equal(right.NewestCheckpointAt)
173	}
