78	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
79		repo, err := strategy.OpenRepository(ctx)
80		if err != nil {
81			cmd.SilenceUsage = true
82			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
83			return NewSilentError(err)
84		}
85	
86		v1Store := checkpoint.NewGitStore(repo)
87		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
88		out := cmd.OutOrStdout()
89	
90		result, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, out, force)
91		if err != nil {
92			return err
93		}
94	
95		repairResult, repairErr := strategy.RepairV2GenerationMetadata(ctx)
96		if repairErr != nil {
97			return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
98		}
99		printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
100	
101		fmt.Fprintf(out, "\nMigration complete: %d migrated, %d skipped, %d failed\n",
102			result.migrated, result.skipped, result.failed)
103		fmt.Fprintln(out)
104		fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
105		fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
106		fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)
107	
108		if result.failed > 0 {
109			fmt.Fprintf(out, "%d checkpoint(s) failed to migrate. Check .entire/logs/ for details.\n", result.failed)
110			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
111		}
112		if repairResult != nil && len(repairResult.Failed) > 0 {
113			fmt.Fprintf(out, "%d archived generation(s) failed metadata repair. Check warnings above for details.\n", len(repairResult.Failed))
114			return NewSilentError(fmt.Errorf("%d archived generation(s) failed metadata repair", len(repairResult.Failed)))
115		}
116	
117		return nil
118	}
