137	var (
138		errAlreadyMigrated          = errors.New("already migrated")
139		errTranscriptNotGeneratable = errors.New("transcript.jsonl could not be generated")
140		errNoMigratableSessions     = errors.New("no migratable v1 sessions")
141	)
