158	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, out io.Writer, force bool) (*migrateResult, error) {
159		v1List, err := v1Store.ListCommitted(ctx)
160		if err != nil {
161			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
162		}
163	
164		if len(v1List) == 0 {
165			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
166			return &migrateResult{}, nil
167		}
168	
169		if force {
170			fmt.Fprintln(out, "Force-migrating v1 checkpoints to v2 (overwriting existing)...")
171		} else {
172			fmt.Fprintln(out, "Migrating v1 checkpoints to v2...")
173		}
174		sortMigratableCheckpoints(v1List)
175		total := len(v1List)
176		result := &migrateResult{}
177		fullCurrentExistsBefore := v2RefExists(repo, plumbing.ReferenceName(paths.V2FullCurrentRefName))
178		var migratedFullCheckpoints []migratedFullCheckpoint
179	
180		for i, info := range v1List {
181			prefix := fmt.Sprintf("  [%d/%d] Migrating checkpoint %s...", i+1, total, info.CheckpointID)
182	
183			fullCheckpoint, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, out, prefix, force)
184			if migrateErr != nil {
185				switch {
186				case errors.Is(migrateErr, errAlreadyMigrated):
187					fmt.Fprintf(out, "%s skipped (already in v2)\n", prefix)
188					result.skipped++
189				case errors.Is(migrateErr, errTranscriptNotGeneratable):
190					fmt.Fprintf(out, "%s in v2, but %s\n", prefix, migrateErr.Error())
191					result.skipped++
192				case errors.Is(migrateErr, errNoMigratableSessions):
193					fmt.Fprintf(out, "%s skipped (%s)\n", prefix, migrateErr.Error())
194					result.skipped++
195				default:
196					fmt.Fprintf(out, "%s failed\n", prefix)
197					logging.Error(ctx, "checkpoint migration failed",
198						slog.String("checkpoint_id", string(info.CheckpointID)),
199						slog.String("error", migrateErr.Error()),
200					)
201					result.failed++
202				}
203				continue
204			}
205	
206			if fullCheckpoint != nil && len(fullCheckpoint.sessions) > 0 {
207				migratedFullCheckpoints = append(migratedFullCheckpoints, *fullCheckpoint)
208			}
209			result.migrated++
210		}
211	
212		if len(migratedFullCheckpoints) > 0 {
213			fmt.Fprintf(out, "Packing raw transcripts into v2 archived generations...\n")
214			if packErr := packMigratedFullGenerations(ctx, repo, v2Store, migratedFullCheckpoints, !fullCurrentExistsBefore); packErr != nil {
215				return result, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
216			}
217		}
218	
219		return result, nil
220	}
