222	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
223		sort.SliceStable(checkpoints, func(i, j int) bool {
224			left := checkpoints[i].CreatedAt
225			right := checkpoints[j].CreatedAt
226			switch {
227			case left.IsZero() && right.IsZero():
228				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
229			case left.IsZero():
230				return false
231			case right.IsZero():
232				return true
233			case left.Equal(right):
234				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
235			default:
236				return left.Before(right)
237			}
238		})
239	}
