246	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, out io.Writer, prefix string, force bool) (*migratedFullCheckpoint, error) {
247		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
248		if err != nil {
249			return nil, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
250		}
251	
252		// Already in v2 — when not forcing, check if any aspect of sessions are missing and backfill
253		if existing != nil && !force {
254			fullCheckpoint, queuedFullRepair, repairErr := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing)
255			if repairErr != nil {
256				return nil, repairErr
257			}
258	
259			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
260			if readCurrentErr != nil {
261				return nil, fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
262			}
263			if currentV2 == nil {
264				return nil, fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
265			}
266	
267			// Clean up v1-named transcript files (full.jsonl, content_hash.txt) that older
268			// CLI versions may have written to /full/current before the rename to raw_transcript.
269			cleanupV1TranscriptFiles(ctx, repo, v2Store, info.CheckpointID, len(currentV2.Sessions))
270	
271			backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2, out, prefix)
272			if errors.Is(backfillErr, errAlreadyMigrated) && queuedFullRepair {
273				fmt.Fprintf(out, "%s queued missing raw transcript artifacts for generation packing\n", prefix)
274				return fullCheckpoint, nil
275			}
276			if errors.Is(backfillErr, errTranscriptNotGeneratable) && queuedFullRepair {
277				fmt.Fprintf(out, "%s queued missing raw transcript artifacts for generation packing (compact transcript not generated)\n", prefix)
278				return fullCheckpoint, nil
279			}
280			if backfillErr != nil {
281				return nil, backfillErr
282			}
283			if queuedFullRepair {
284				fmt.Fprintf(out, "%s queued missing raw transcript artifacts for generation packing\n", prefix)
285				return fullCheckpoint, nil
286			}
287			return &migratedFullCheckpoint{}, nil
288		}
289	
290		if existing != nil && force {
291			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
292				return nil, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
293			}
294		}
295	
296		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
297		if err != nil {
298			return nil, fmt.Errorf("failed to read v1 summary: %w", err)
299		}
300		if summary == nil {
301			return nil, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
302		}
303	
304		compactFailed := false
305		shouldCopyTaskMetadata := false
306		skippedMissingSessions := 0
307		migratedSessions := 0
308		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
309		fullCheckpoint := &migratedFullCheckpoint{
310			checkpointID: info.CheckpointID,
311		}
312	
313		for sessionIdx := range len(summary.Sessions) {
314			content, skipped, readErr := readV1SessionForMigration(ctx, out, prefix, v1Store, info.CheckpointID, sessionIdx)
315			if skipped {
316				skippedMissingSessions++
317				continue
318			}
319			if readErr != nil {
320				return nil, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
321			}
322			if content.Metadata.IsTask {
323				shouldCopyTaskMetadata = true
324			}
325	
326			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
327	
328			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
329			if compacted != nil {
330				opts.CompactTranscript = compacted
331				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
332			} else if len(content.Transcript) > 0 {
333				compactFailed = true
334			}
335	
336			mainOpts := opts
337			mainOpts.Transcript = redact.AlreadyRedacted(nil)
338			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
339			if writeErr != nil {
340				return nil, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
341			}
342			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
343			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
344				sessionIndex: v2SessionIdx,
345				content:      content,
346			})
347			migratedSessions++
348		}
349	
350		if migratedSessions == 0 {
351			return nil, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
352		}
353	
354		if shouldCopyTaskMetadata {
355			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
356			if taskErr != nil {
357				logging.Warn(ctx, "failed to copy task metadata to v2",
358					slog.String("checkpoint_id", string(info.CheckpointID)),
359					slog.String("error", taskErr.Error()),
360				)
361			} else {
362				fullCheckpoint.taskTrees = taskTrees
363			}
364		}
365	
366		switch {
367		case compactFailed && skippedMissingSessions > 0:
368			fmt.Fprintf(out, "%s done (compact transcript not generated; skipped %d session(s) with missing transcript/session content)\n", prefix, skippedMissingSessions)
369		case compactFailed:
370			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
371		case skippedMissingSessions > 0:
372			fmt.Fprintf(out, "%s done (skipped %d session(s) with missing transcript/session content)\n", prefix, skippedMissingSessions)
373		default:
374			fmt.Fprintf(out, "%s done\n", prefix)
375		}
376	
377		return fullCheckpoint, nil
378	}
379	
380	func packMigratedFullGenerations(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, checkpoints []migratedFullCheckpoint, ensureEmptyCurrent bool) error {
381		if len(checkpoints) == 0 {
382			if ensureEmptyCurrent {
383				return ensureEmptyV2FullCurrent(ctx, repo)
384			}
385			return nil
386		}
387	
388		batchSize := migrateMaxCheckpointsPerGeneration
389		if batchSize <= 0 {
390			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
391		}
392	
393		nextGeneration, err := nextMigratedGenerationNumber(v2Store)
394		if err != nil {
395			return err
396		}
397	
398		for start := 0; start < len(checkpoints); start += batchSize {
399			end := min(start+batchSize, len(checkpoints))
400	
401			refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, nextGeneration))
402			if err := writeMigratedFullGeneration(ctx, repo, refName, checkpoints[start:end]); err != nil {
403				return err
404			}
405			nextGeneration++
406		}
407	
408		if ensureEmptyCurrent {
409			return ensureEmptyV2FullCurrent(ctx, repo)
410		}
411		return nil
412	}
413	
414	func nextMigratedGenerationNumber(v2Store *checkpoint.V2GitStore) (int, error) {
415		archived, err := v2Store.ListArchivedGenerations()
416		if err != nil {
417			return 0, fmt.Errorf("list archived v2 generations: %w", err)
418		}
419		next := 1
420		for _, name := range archived {
421			n, parseErr := strconv.Atoi(name)
422			if parseErr != nil {
423				continue
424			}
425			if n >= next {
426				next = n + 1
427			}
428		}
429		return next, nil
430	}
