432	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
433		entries := make(map[string]object.TreeEntry)
434		var gen checkpoint.GenerationMetadata
435		foundTime := false
436	
437		for _, cp := range checkpoints {
438			for _, session := range cp.sessions {
439				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
440					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
441				}
442				mergeMigratedGenerationTime(&gen, &foundTime, session.content.Metadata.CreatedAt)
443			}
444		}
445	
446		if !foundTime {
447			now := time.Now().UTC()
448			gen = checkpoint.GenerationMetadata{
449				OldestCheckpointAt: now,
450				NewestCheckpointAt: now,
451			}
452		}
453	
454		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
455		if err != nil {
456			return fmt.Errorf("build migrated generation tree: %w", err)
457		}
458	
459		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
460		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
461		if err != nil {
462			return fmt.Errorf("add generation metadata: %w", err)
463		}
464	
465		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
466			fmt.Sprintf("Archive migrated generation: %s\n", refName),
467			"Entire Migration", "migration@entire.dev")
468		if err != nil {
469			return fmt.Errorf("create migrated generation commit: %w", err)
470		}
471	
472		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
473			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
474		}
475		return nil
476	}
