478	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
479		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
480		transcript := session.content.Transcript
481	
482		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
483		if err != nil {
484			return fmt.Errorf("chunk transcript: %w", err)
485		}
486		for i, chunk := range chunks {
487			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
488			if blobErr != nil {
489				return fmt.Errorf("create transcript blob: %w", blobErr)
490			}
491			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
492			entries[path] = object.TreeEntry{
493				Name: path,
494				Mode: filemode.Regular,
495				Hash: blobHash,
496			}
497		}
498	
499		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
500		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
501		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
502		if err != nil {
503			return fmt.Errorf("create transcript hash blob: %w", err)
504		}
505		entries[hashPath] = object.TreeEntry{
506			Name: hashPath,
507			Mode: filemode.Regular,
508			Hash: hashBlob,
509		}
510	
511		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
512			taskTree, treeErr := repo.TreeObject(taskTreeHash)
513			if treeErr != nil {
514				return fmt.Errorf("read task metadata tree: %w", treeErr)
515			}
516			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", entries); flattenErr != nil {
517				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
518			}
519		}
520	
521		return nil
522	}
