524	func mergeMigratedGenerationTime(gen *checkpoint.GenerationMetadata, found *bool, ts time.Time) {
525		if ts.IsZero() {
526			return
527		}
528		ts = ts.UTC()
529		if !*found {
530			gen.OldestCheckpointAt = ts
531			gen.NewestCheckpointAt = ts
532			*found = true
533			return
534		}
535		if ts.Before(gen.OldestCheckpointAt) {
536			gen.OldestCheckpointAt = ts
537		}
538		if ts.After(gen.NewestCheckpointAt) {
539			gen.NewestCheckpointAt = ts
540		}
541	}
