588	func pruneV2CheckpointForForce(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID) error {
589		for _, refName := range []plumbing.ReferenceName{
590			plumbing.ReferenceName(paths.V2MainRefName),
591			plumbing.ReferenceName(paths.V2FullCurrentRefName),
592		} {
593			if err := pruneV2CheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
594				return err
595			}
596		}
597	
598		archived, err := v2Store.ListArchivedGenerations()
599		if err != nil {
