612	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
613		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
614		if err != nil {
615			if errors.Is(err, plumbing.ErrReferenceNotFound) {
616				return nil
617			}
618			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
619		}
620	
621		rootTree, err := repo.TreeObject(rootTreeHash)
622		if err != nil {
623			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
624		}
625		if _, err := rootTree.Tree(cpID.Path()); err != nil {
626			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
627		}
628	
629		shardPrefix := string(cpID[:2])
630		shardSuffix := string(cpID[2:])
631		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
632		if err != nil {
633			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
634		}
635		if newRoot == rootTreeHash {
636			return nil
637		}
638	
639		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
640			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
641			"Entire Migration", "migration@entire.dev")
642		if err != nil {
643			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
644		}
645	
646		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
647			return fmt.Errorf("failed to update ref %s: %w", refName, err)
648		}
649		return nil
650	}
651	
652	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
653		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
654		if err != nil {
655			if errors.Is(err, plumbing.ErrReferenceNotFound) {
656				return nil
657			}
658			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
659		}
660	
661		rootTree, err := repo.TreeObject(rootTreeHash)
662		if err != nil {
663			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
664		}
665		if _, err := rootTree.Tree(cpID.Path()); err != nil {
666			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
667		}
668	
669		shardPrefix := string(cpID[:2])
670		shardSuffix := string(cpID[2:])
671		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
672		if err != nil {
673			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
674		}
675		if newRoot == rootTreeHash {
676			return nil
677		}
678	
679		count, err := v2Store.CountCheckpointsInTree(newRoot)
680		if err != nil {
681			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
682		}
683		if count == 0 {
684			if err := repo.Storer.RemoveReference(refName); err != nil {
685				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
686			}
687			return nil
688		}
689	
690		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
691		if err != nil {
692			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
693		}
694	
695		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
696			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
697			"Entire Migration", "migration@entire.dev")
698		if err != nil {
699			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
700		}
701	
702		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
703			return fmt.Errorf("failed to update ref %s: %w", refName, err)
704		}
705		return nil
706	}
