708	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
709		gen, found, err := v2Store.ComputeGenerationRawTranscriptTimestamps(treeHash)
710		if err != nil {
711			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
712		}
713		if !found {
714			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
715			if err != nil {
716				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
717			}
718		}
719		if !found {
720			return treeHash, nil
721		}
722	
723		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
724		if err != nil {
725			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
726		}
727		return newTreeHash, nil
728	}
729	
730	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
731		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
732			[]string{shardPrefix},
733			nil,
734			checkpoint.UpdateSubtreeOptions{
735				MergeMode:   checkpoint.MergeKeepExisting,
736				DeleteNames: []string{shardSuffix},
737			},
738		)
739		if err != nil {
740			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
741		}
742		if newRoot == rootTreeHash {
743			return newRoot, nil
744		}
745	
746		newRootTree, err := repo.TreeObject(newRoot)
747		if err != nil {
748			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
749		}
750		shardTree, err := newRootTree.Tree(shardPrefix)
751		if err != nil {
752			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
753		}
754		if len(shardTree.Entries) > 0 {
755			return newRoot, nil
756		}
757	
758		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
759			nil,
760			nil,
761			checkpoint.UpdateSubtreeOptions{
762				MergeMode:   checkpoint.MergeKeepExisting,
763				DeleteNames: []string{shardPrefix},
764			},
765		)
766		if err != nil {
767			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
768		}
769		return prunedRoot, nil
770	}
