772	func collectMissingFullCheckpointForPacking(
773		ctx context.Context,
774		repo *git.Repository,
775		v1Store *checkpoint.GitStore,
776		v2Store *checkpoint.V2GitStore,
777		info checkpoint.CommittedInfo,
778		v2Summary *checkpoint.CheckpointSummary,
779	) (*migratedFullCheckpoint, bool, error) {
780		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
781		if err != nil {
782			return nil, false, fmt.Errorf("failed to read v1 summary while checking v2 raw artifacts: %w", err)
783		}
784		if v1Summary == nil {
785			return nil, false, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
786		}
787	
788		v1BySessionID, v1ByIndex, err := collectV1SessionsForPacking(ctx, v1Store, info.CheckpointID, v1Summary)
789		if err != nil {
790			return nil, false, err
791		}
792	
793		fullCheckpoint := &migratedFullCheckpoint{
794			checkpointID: info.CheckpointID,
795		}
796		v1ToV2SessionIdx := make(map[int]int)
797	
798		for sessionIdx := range len(v2Summary.Sessions) {
799			ok, checkErr := hasFullSessionArtifacts(v2Store, info.CheckpointID, sessionIdx)
800			if checkErr != nil {
801				return nil, false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
802			}
803			if ok {
804				continue
805			}
806	
807			v2Content, readErr := v2Store.ReadSessionMetadataAndPrompts(ctx, info.CheckpointID, sessionIdx)
808			if readErr != nil {
809				return nil, false, fmt.Errorf("failed to read v2 session %d metadata while checking raw artifacts: %w", sessionIdx, readErr)
810			}
811	
812			v1Session, ok := v1BySessionID[v2Content.Metadata.SessionID]
813			if !ok {
814				v1Session, ok = v1ByIndex[sessionIdx]
815			}
816			if !ok {
817				return nil, false, fmt.Errorf("failed to find v1 session for v2 session %d while checking raw artifacts", sessionIdx)
818			}
819	
820			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
821				sessionIndex: sessionIdx,
822				content:      v1Session.content,
823			})
824			v1ToV2SessionIdx[v1Session.sessionIndex] = sessionIdx
825		}
826	
827		if len(fullCheckpoint.sessions) == 0 {
828			return &migratedFullCheckpoint{}, false, nil
829		}
830	
831		taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, v1Summary, v1ToV2SessionIdx)
832		if taskErr != nil {
833			return nil, false, fmt.Errorf("failed to collect task metadata while checking raw artifacts: %w", taskErr)
834		}
835		fullCheckpoint.taskTrees = taskTrees
836	
837		return fullCheckpoint, true, nil
838	}
