845	func collectV1SessionsForPacking(
846		ctx context.Context,
847		v1Store *checkpoint.GitStore,
848		checkpointID id.CheckpointID,
849		summary *checkpoint.CheckpointSummary,
850	) (map[string]v1SessionForPacking, map[int]v1SessionForPacking, error) {
851		bySessionID := make(map[string]v1SessionForPacking)
852		byIndex := make(map[int]v1SessionForPacking)
853	
854		for sessionIdx := range len(summary.Sessions) {
855			content, err := v1Store.ReadSessionContent(ctx, checkpointID, sessionIdx)
856			if err != nil {
857				if errors.Is(err, checkpoint.ErrNoTranscript) || errors.Is(err, checkpoint.ErrCheckpointNotFound) {
858					continue
859				}
860				return nil, nil, fmt.Errorf("failed to read v1 session %d while checking raw artifacts: %w", sessionIdx, err)
861			}
862	
863			session := v1SessionForPacking{
864				sessionIndex: sessionIdx,
865				content:      content,
866			}
867			byIndex[sessionIdx] = session
868			if content.Metadata.SessionID != "" {
869				bySessionID[content.Metadata.SessionID] = session
870			}
871		}
872	
873		return bySessionID, byIndex, nil
874	}
