884	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
885	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
886	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
887	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
888		// Find sessions missing transcript.jsonl
889		var needsBackfill []int
890		for i, session := range v2Summary.Sessions {
891			if session.Transcript == "" {
892				needsBackfill = append(needsBackfill, i)
893			}
894		}
895	
896		if len(needsBackfill) == 0 {
897			return errAlreadyMigrated
898		}
899	
900		backfilled := 0
901		var lastAgent string
902	
903		for _, sessionIdx := range needsBackfill {
904			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
905			if readErr != nil {
906				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
907					slog.String("checkpoint_id", string(info.CheckpointID)),
908					slog.Int("session_index", sessionIdx),
909					slog.String("error", readErr.Error()),
910				)
911				continue
912			}
913	
914			if content.Metadata.Agent != "" {
915				lastAgent = string(content.Metadata.Agent)
916			}
917	
918			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
919			if compacted == nil {
920				// tryCompactTranscript already logs for no-agent and compact-error cases;
921				// log the empty-transcript case here.
922				if len(content.Transcript) == 0 {
923					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
924						slog.String("checkpoint_id", string(info.CheckpointID)),
925						slog.Int("session_index", sessionIdx),
926					)
927				}
928				continue
929			}
930	
931			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
932				CheckpointID:      info.CheckpointID,
933				SessionID:         content.Metadata.SessionID,
934				CompactTranscript: compacted,
935			})
936			if updateErr != nil {
937				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
938					slog.String("checkpoint_id", string(info.CheckpointID)),
939					slog.Int("session_index", sessionIdx),
940					slog.String("error", updateErr.Error()),
941				)
942				continue
943			}
944	
945			backfilled++
946		}
947	
948		if backfilled == 0 {
949			if lastAgent != "" {
950				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
951			}
952			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
953		}
954	
955		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
956	
957		return nil
958	}
