960	func buildMigrateWriteOpts(content *checkpoint.SessionContent, info checkpoint.CommittedInfo, combinedAttribution *checkpoint.InitialAttribution) checkpoint.WriteCommittedOptions {
961		m := content.Metadata
962	
963		prompts := checkpoint.SplitPromptContent(content.Prompts)
964	
965		return checkpoint.WriteCommittedOptions{
966			CheckpointID: info.CheckpointID,
967			SessionID:    m.SessionID,
968			CreatedAt:    m.CreatedAt,
969			Strategy:     m.Strategy,
970			Branch:       m.Branch,
971			// content.Transcript comes from persisted checkpoint storage and is
972			// already redacted.
973			Transcript:                  redact.AlreadyRedacted(content.Transcript),
974			Prompts:                     prompts,
975			FilesTouched:                m.FilesTouched,
976			CheckpointsCount:            m.CheckpointsCount,
977			Agent:                       m.Agent,
978			Model:                       m.Model,
979			TurnID:                      m.TurnID,
980			TokenUsage:                  m.TokenUsage,
