		if repairErr != nil {
			result.Failed = append(result.Failed, candidate.Name)
			result.Warnings = append(result.Warnings, fmt.Sprintf("generation %s: %v", candidate.Name, repairErr))
			continue
		}
		if repaired {
			result.Repaired = append(result.Repaired, candidate.Name)
